3	function escapeRegExp(s) {
4	  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
5	}
6	
7	function slugify(title, { maxLength = 80, separator = '-' } = {}) {
8	  const sep = escapeRegExp(separator);
9	  let slug = String(title)
10	    .normalize('NFD')
11	    .replace(/[̀-ͯ]/g, '') // drop accents: é -> e
12	    .toLowerCase()
13	    .replace(/[^a-z0-9]+/g, separator)
14	    .replace(new RegExp(`^${sep}|${sep}$`), '');
15	
16	  if (slug.length > maxLength) {
17	    const cut = slug.slice(0, maxLength + 1);
18	    const lastSep = cut.lastIndexOf(separator);
19	    slug = lastSep > 0 ? cut.slice(0, lastSep) : slug.slice(0, maxLength);
20	  }
21	  return slug;
22	}
23	
24	module.exports = { slugify };
